--- 迷宫内玩家控制
local Singleton = import('Frame.Singleton')
local ResourceModule = CS.Engine.Modules.ResourceModule
local GameObject = CS.UnityEngine.GameObject
local KTool = CS.Engine.Lib.KTool
local Animator = CS.UnityEngine.Animator
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local URPBaseCamera = CS.Game.Native.URP.URPBaseCamera

local gameUtils = GameUtils
---@class MazePlayerMgr
---@field GetInstance fun(self:MazePlayerMgr):MazePlayerMgr
local MazePlayerMgr = Class("MazePlayerMgr", Singleton)
---@type MazeMapMgr
local MazeMapMgr = import('Game.Maze.MazeMapMgr')

function MazePlayerMgr:__init()
    self.themeVo = nil
    self.animator = nil
    self.playerPar = nil       --人物节点
    self.playerGo = nil        --人物预设

    self.moveTime = 0          --移动时间
    self.rotaTime = 0          --旋转时间
    self.enterTime = 0      --enter动作播放的时间
    self.prepareTime = 0      --跳跃准备时间
    self.autoV = nil           --默认rotat向量

    self.isPlayerMovIng = false
end

function MazePlayerMgr:__delete()
    self.themeVo = nil
    self.animator = nil
    self.playerPar = nil       --人物节点
    self.playerGo = nil        --人物预设

    self.prepareTime = 0      --跳跃准备时间
    self.moveTime = 0    --移动时间
    self.rotaTime = 0    --旋转时间
    self.enterTime = 0      --enter动作播放的时间
    self.autoV = nil     --默认rotat向量

