end

--主题类型配表数据
function MazePlayerMgr:Init(themeVo)
    self.themeVo = themeVo
    self.playerPar = GameObject.Find("Player").transform
    self.autoV = self.playerPar.transform.forward

    --local mazeCam = MazeMapMgr:GetInstance().mazeCam
    MazeMapMgr:GetInstance():SetPlayerDis(self.playerPar)

    self:InitPlayer()
end

---Init
---初始化人物
function MazePlayerMgr:InitPlayer()
    if not self.themeVo then
        return
    end

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting365, "MazeStarringSettingVo", checkString(self.themeVo.starringId))
    if not vo then
        return
    end
    local go
    if IsNull(self.playerLoader) then
        self.playerLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync(vo.modelPath, nil, true)
        if self.playerLoader.IsSuccess then
            go = CfUtils.InstantiateGo(self.playerLoader.ResultObject, self.playerPar)
        end
    end
    if go then
        go.name = "player"
        go.transform.localPosition = Vector3(0, 0, 0)
        self.playerGo = go
        KTool.SetActive(self.playerGo, true)

        self.animator = go:GetComponent(typeof(Animator))

        local animCtrl
        if IsNull(self.controllerLoader) then
            self.controllerLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync(vo.controllerPath, nil, true)
            if self.controllerLoader.IsSuccess then
                animCtrl = GameObject.Instantiate(self.controllerLoader.ResultObject)
            end
        end
        if animCtrl then
            self.animator.runtimeAnimatorController = animCtrl
            self.animatorLayIndex = self.animator:GetLayerIndex("Base Layer")
        end

        --禁用掉角色身上无用的脚本
        local scr = go:GetComponent("PlaneShadow")
        if scr then
            scr.enabled = false
        end
        scr = go:GetComponent("MatcapEffectManager")
        if scr then
            scr.enabled = false
        end
    end

    self.enterTime = self:GetAnimatorTime(Constants.MazeRoleAnimatorType.Enter)
    self.moveTime = self:GetAnimatorTime(Constants.MazeRoleAnimatorType.Jump)
    self.prepareTime = self:GetAnimatorTime(Constants.MazeRoleAnimatorType.Prepare)
end

---MovePlayer  人物移动
---@param poiint MazeMapPointDojo
function MazePlayerMgr:MovePlayer(point, isInitPlayer)
    local cam = MazeMapMgr:GetInstance():GetMazeCamera()
    --先拿位置
    local pos = MazeMapMgr:GetInstance():GetBuildActPos(point)
    if not pos then
        return
    end
    local urpBase = cam:GetComponent(typeof(URPBaseCamera))

    --如果是刚进场景初始化角色  直接刷新位置
    if isInitPlayer then
        self.playerPar.transform.position = Vector3(pos.x, pos.y, pos.z)
        if cam then
            cam.transform.position = Vector3(pos.x, pos.y, pos.z) + MazeMapMgr:GetInstance():GetPlayerDis()
            urpBase:CopyCamera()
        end
        if MazeMapMgr:GetInstance():IsFirstPoint(point) then
            self:PlayerAnimator(Constants.MazeRoleAnimatorType.Enter)
        end
        return
    end
    if self.isPlayerMovIng then return end
    self.isPlayerMovIng = true

    self.moveCor = cs_coroutine.start(function()
        self:PlayerAnimator(Constants.MazeRoleAnimatorType.Prepare)
        coroutine.yield(WaitForSeconds(self.prepareTime))
        self:PlayerAnimator(Constants.MazeRoleAnimatorType.Jump)
        coroutine.yield(WaitForSeconds(0.145))
        --[[
        CfUtils.ArcMove(self.playerPar, self.playerPar.transform.position, Vector3(pos.x, pos.y, pos.z), self.moveTime - 0.2, function()
            --self:RefeshPlayerRota()
            self.isPlayerMovIng = false
        end)
        ]]
        local _roleFrom = self.playerPar.transform.position
        local _roleTo = Vector3(pos.x, pos.y, pos.z)
        CfUtils.DoTween(0.434, function(updateValue)
            self.playerPar.transform.position = CS.UnityEngine.Vector3.Slerp(_roleFrom, _roleTo, updateValue)
        end, function()
            self.isPlayerMovIng = false
        end)
        
        local _mazeFrom = cam.transform.position
        local _mazeTo = Vector3(pos.x, pos.y, pos.z) + MazeMapMgr:GetInstance():GetPlayerDis()
        CfUtils.DoTween(0.434, function(updateValue)
            cam.transform.position = CS.UnityEngine.Vector3.Slerp(_mazeFrom, _mazeTo, updateValue)
            urpBase:CopyCamera()
        end)
    end)
end 

---PlayerLookPoint  人物角度转向点
---@param point MazeMapPointDojo
---@param callBack fun():void
function MazePlayerMgr:PlayerLookPoint(point, callBack)
    if self.isPlayerMovIng then return end
    self.isPlayerMovIng = true
    
    local pos = MazeMapMgr:GetInstance():GetBuildActPos(point)
    local normalV = pos - self.playerPar.transform.position
    --normalV = normalV * self.playerPar.transform.forward
    self:PlayerRotateTween(self.playerPar.transform.forward, normalV, self.rotaTime, function()
        Events.Broadcast(Constants.EventNames.MazeUpdataPreview)
    end, function()
        if callBack then
            callBack()
        end
    end)
end

---RefeshPlayerRota  移动完之后人物的视角刷新
function MazePlayerMgr:RefeshPlayerRota(updateCb, endCb)
    if not self.isPlayerMovIng then
        self.isPlayerMovIng = true
    end

    local normalV = self.autoV
    self:PlayerRotateTween(self.playerPar.transform.forward, normalV, self.rotaTime, function()
        if updateCb then
            updateCb()
        end
    end, endCb)
end

--旋转动画
function MazePlayerMgr:PlayerRotateTween(fromV, toV, time, updateCb, endCb)
    if not fromV or not toV then return end
    
    local rot = CfUtils.GetVectorAngle(fromV, toV)
    local formRot = self.playerPar.transform.localRotation
    CfUtils.DoTween(time, function(updateValue)
        local rotation = Quaternion.New()
        rotation.eulerAngles = Vector3.New(0, rot*updateValue + formRot.eulerAngles.y, 0)
        self.playerPar.transform.localRotation = rotation
        if updateCb then
            updateCb()
        end
    end, function()
        if endCb then
            endCb()
        end
        self.isPlayerMovIng = false
    end)
end

--播放动作
function MazePlayerMgr:PlayerAnimator(type)
    if not self.animator then
        return
    end
    self.animator:Play(self:GetAnimatorName(type), self.animatorLayIndex, 0)
end

--获取条件名字
function MazePlayerMgr:GetAnimatorName(type)
    type = checkNumber(type)
    local name
    if not self.themeVo then 
        return name
    end

    if type == Constants.MazeRoleAnimatorType.Enter then
        name = "enter"
    elseif type == Constants.MazeRoleAnimatorType.Prepare then
        name = "prepare2"
    elseif type == Constants.MazeRoleAnimatorType.Jump then
        name = "jump"
    end
    return name
end 

--获取动作播放时间
function MazePlayerMgr:GetAnimatorTime(type)
    local length = 0
    if not self.animator then
        return length
    end

    local clips = self.animator.runtimeAnimatorController.animationClips
    for i = 1, clips.Length do
        local v = clips[i - 1]
        if type == Constants.MazeRoleAnimatorType.Enter then
            if v.name == "enter" then
                length = checkNumber(v.length) + length
                return length
            end
        elseif type == Constants.MazeRoleAnimatorType.Prepare then
            if v.name == "prepare2" then
                length = checkNumber(v.length) + length
                return length
            end
        --跳跃
        elseif type == Constants.MazeRoleAnimatorType.Jump then
            if v.name == "jump" then
                length = checkNumber(v.length) + length
                return length
            end
        end
    end
    return length
end

function MazePlayerMgr:Clear()
    if self.isPlayerMovIng then
        self.isPlayerMovIng = false
    end
    if not isNull(self.controllerLoader) then
        self.controllerLoader:Release(true)
        self.controllerLoader = nil
    end
    if not isNull(self.playerLoader) then
        self.playerLoader:Release(true)
        self.playerLoader = nil
    end

    --self:__delete()
    self.Destroy(self)
end

return MazePlayerMgr
